public class HttpConnectionTest {
    private Connection connection;

    @Before
    public void setup() {
        this.connection = new HttpConnection();
    }

    public void testConnectWithNullUrl() throws IOException, InterruptedException {
        String url = null;
        String expectedOutput = "HTTP/1.1 404 Not Found\r\n\r\n";
        System.out.println(connection.connect(url));
        assertEquals(expectedOutput, connection.get());
    }

    public void testConnectWithInvalidUrl() throws IOException {
        String url = "http:invalid-url.com";
        String expectedOutput = "HTTP/1.1 404 Not Found\r\n\r\n";
        System.out.println(connection.connect(url));
        assertEquals(expectedOutput, connection.get());
    }

    public void testConnectWithValidUrl() throws IOException {
        String url = new URL("https://example.com");
        String expectedOutput = "HTTP/1.1 200 OK\r\nHost: example.com\r\nContent-Type: text/html\r\n\r\n<html>\r\n<head>\r\n<title>Example</title>\r\n<\/head>\r\n<body>\r\n<p>Hello World!</p>\r\n<\/body>\r\n</html>";
        System.out.println(connection.connect(url));
        assertEquals(expectedOutput, connection.get());
    }

    public void testConnectWithCookies() throws IOException {
        String url = new URL("https://example.com");
        CookieManager cookieManager = new CookieManager();
