        String expectedOutput = "HTTP/1.1 200 OK\r\nHost: example.com\r\nSet-Cookie: test_cookie=test_value; Path=/; Expires=Thu, 01 Jan 1970 00:00:00 GMT\r\n\r\n<html>\r\n<head>\r\n<title>Example</title>\r\n<\/head>\r\n<body>\r\n<p>Hello World!</p>\r\n<\/body>\r\n</html>";
